    svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 720 360" width="100%" role="img" font-family="Atkinson Hyperlegible, Verdana, sans-serif" text-anchor="middle"><title>Audience profile and directions of flow</title><defs><marker id="ah-m3u2" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="var(--muted)"/></marker></defs><rect x="1" y="1" width="718" height="358" rx="14" fill="var(--raise)" stroke="var(--line)" stroke-width="1.5"/><text x="24" y="34" font-size="16" fill="var(--ink)" text-anchor="start" font-weight="700">Profile your audience</text><rect x="20" y="50" width="318" height="286" rx="12" fill="var(--surface)" stroke="var(--line)" stroke-width="1.5"/><circle cx="60" cy="92" r="20" fill="var(--soft-blue)" stroke="var(--blue)" stroke-width="1.5"/><circle cx="60" cy="86" r="7" fill="var(--blue)" stroke="none" stroke-width="1.5"/><path d="M47 104Q60 92 73 104" fill="none" stroke="var(--blue)" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/><text x="92" y="98" font-size="15" fill="var(--ink)" text-anchor="start" font-weight="700">Who is listening?</text><rect x="36" y="124" width="6" height="44" rx="3" fill="var(--gold)" stroke="none" stroke-width="1.5"/><text x="54" y="142" font-size="15" fill="var(--ink)" text-anchor="start" font-weight="700">Age</text><text x="54" y="162" font-size="13" fill="var(--muted)" text-anchor="start">shapes tone and examples</text><rect x="36" y="186" width="6" height="44" rx="3" fill="var(--gold)" stroke="none" stroke-width="1.5"/><text x="54" y="204" font-size="15" fill="var(--ink)" text-anchor="start" font-weight="700">Education</text><text x="54" y="224" font-size="13" fill="var(--muted)" text-anchor="start">shapes vocabulary and detail</text><rect x="36" y="248" width="6" height="56" rx="3" fill="var(--gold)" stroke="none" stroke-width="1.5"/><text x="54" y="266" font-size="15" fill="var(--ink)" text-anchor="start" font-weight="700">Location</text><text x="54" y="286" font-size="13" fill="var(--muted)" text-anchor="start">shapes the medium: radio,</text><text x="54" y="304" font-size="13" fill="var(--muted)" text-anchor="start">flyer, app or meeting</text><text x="530" y="34" font-size="16" fill="var(--ink)" font-weight="700">Directions of flow</text><rect x="468" y="52" width="124" height="42" rx="10" fill="var(--blue)" stroke="var(--blue)" stroke-width="1.5"/><text x="530" y="79" font-size="15" fill="var(--on-blue)" font-weight="700">Manager</text><rect x="378" y="210" width="124" height="42" rx="10" fill="var(--soft-blue)" stroke="var(--blue)" stroke-width="1.5"/><text x="440" y="237" font-size="15" fill="var(--ink)" font-weight="700">Staff A</text><rect x="558" y="210" width="124" height="42" rx="10" fill="var(--soft-blue)" stroke="var(--blue)" stroke-width="1.5"/><text x="620" y="237" font-size="15" fill="var(--ink)" font-weight="700">Staff B</text><line x1="498" y1="96" x2="448" y2="206" fill="none" stroke="var(--muted)" stroke-width="2" marker-end="url(#ah-m3u2)"/><line x1="612" y1="206" x2="562" y2="96" fill="none" stroke="var(--muted)" stroke-width="2" marker-end="url(#ah-m3u2)"/><line x1="506" y1="231" x2="554" y2="231" fill="none" stroke="var(--muted)" stroke-width="2" marker-end="url(#ah-m3u2)" marker-start="url(#ah-m3u2)"/><text x="462" y="138" font-size="13" fill="var(--ink)" text-anchor="end">Downward:</text><text x="462" y="156" font-size="13" fill="var(--ink)" text-anchor="end">instructions</text><text x="598" y="138" font-size="13" fill="var(--ink)" text-anchor="start">Upward:</text><text x="598" y="156" font-size="13" fill="var(--ink)" text-anchor="start">reports,</text><text x="598" y="174" font-size="13" fill="var(--ink)" text-anchor="start">feedback</text><text x="530" y="282" font-size="13" fill="var(--ink)">Horizontal: between colleagues</text><text x="530" y="304" font-size="13" fill="var(--muted)">at the same level</text></svg>',
    alt: 'An audience profile card covering age, education and location, beside an organisation chart showing downward, upward and horizontal flows of communication.',
