    svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 720 360" width="100%" role="img" font-family="Atkinson Hyperlegible, Verdana, sans-serif" text-anchor="middle"><title>Choosing media for a rural audience</title><defs><marker id="ah-p3u2" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="var(--muted)"/></marker></defs><rect x="1" y="1" width="718" height="358" rx="14" fill="var(--raise)" stroke="var(--line)" stroke-width="1.5"/><rect x="18" y="40" width="220" height="280" rx="12" fill="var(--soft-blue)" stroke="var(--blue)" stroke-width="1.5"/><text x="128" y="72" font-size="16" fill="var(--ink)" font-weight="700">Target audience</text><circle cx="128" cy="120" r="26" fill="var(--blue)" stroke="none" stroke-width="1.5"/><circle cx="128" cy="110" r="9" fill="var(--on-blue)" stroke="none" stroke-width="1.5"/><path d="M112 134Q128 118 144 134" fill="none" stroke="var(--on-blue)" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/><text x="128" y="174" font-size="14" fill="var(--ink)" font-weight="700">Elderly homeowners</text><text x="128" y="194" font-size="14" fill="var(--ink)" font-weight="700">in a rural village</text><text x="128" y="230" font-size="13" fill="var(--muted)">weak internet signal</text><text x="128" y="252" font-size="13" fill="var(--muted)">often busy with chores</text><text x="128" y="274" font-size="13" fill="var(--muted)">trust familiar voices</text><rect x="256" y="40" width="446" height="60" rx="10" fill="var(--surface)" stroke="var(--blue)" stroke-width="1.5"/><circle cx="282" cy="70" r="11" fill="var(--blue)" stroke="none" stroke-width="1.5"/><path d="M276.5 70l4 4l7-8" fill="none" stroke="var(--on-blue)" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/><text x="304" y="65" font-size="15" fill="var(--ink)" text-anchor="start" font-weight="700">Radio</text><text x="304" y="85" font-size="13" fill="var(--muted)" text-anchor="start">cheap, reaches rural areas, heard during chores</text><rect x="256" y="110" width="446" height="60" rx="10" fill="var(--surface)" stroke="var(--blue)" stroke-width="1.5"/><circle cx="282" cy="140" r="11" fill="var(--blue)" stroke="none" stroke-width="1.5"/><path d="M276.5 140l4 4l7-8" fill="none" stroke="var(--on-blue)" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/><text x="304" y="135" font-size="15" fill="var(--ink)" text-anchor="start" font-weight="700">Community meeting</text><text x="304" y="155" font-size="13" fill="var(--muted)" text-anchor="start">trusted local speakers, questions answered</text><rect x="256" y="180" width="446" height="60" rx="10" fill="var(--surface)" stroke="var(--gold)" stroke-width="1.5"/><circle cx="282" cy="210" r="11" fill="var(--soft-gold)" stroke="var(--gold)" stroke-width="1.5"/><path d="M278 206l8 8m0-8l-8 8" fill="none" stroke="var(--ink)" stroke-width="2.5" stroke-linecap="round"/><text x="304" y="205" font-size="15" fill="var(--ink)" text-anchor="start" font-weight="700">Social media app</text><text x="304" y="225" font-size="13" fill="var(--muted)" text-anchor="start">weak signal; low use by older residents</text><rect x="256" y="250" width="446" height="60" rx="10" fill="var(--surface)" stroke="var(--gold)" stroke-width="1.5"/><circle cx="282" cy="280" r="11" fill="var(--soft-gold)" stroke="var(--gold)" stroke-width="1.5"/><path d="M278 276l8 8m0-8l-8 8" fill="none" stroke="var(--ink)" stroke-width="2.5" stroke-linecap="round"/><text x="304" y="275" font-size="15" fill="var(--ink)" text-anchor="start" font-weight="700">Website</text><text x="304" y="295" font-size="13" fill="var(--muted)" text-anchor="start">needs internet access and digital skills</text><text x="360" y="340" font-size="15" fill="var(--ink)" font-weight="700">Justify: medium + feature + link to THIS audience</text></svg>',
