    svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 720 360" width="100%" role="img" font-family="Atkinson Hyperlegible, Verdana, sans-serif" text-anchor="middle"><title>Slogan techniques</title><defs><marker id="ah-p3u3" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="var(--muted)"/></marker></defs><rect x="1" y="1" width="718" height="358" rx="14" fill="var(--raise)" stroke="var(--line)" stroke-width="1.5"/><text x="24" y="30" font-size="17" fill="var(--ink)" text-anchor="start" font-weight="700">Slogan techniques</text><rect x="20" y="44" width="172" height="48" rx="24" fill="var(--gold)" stroke="none" stroke-width="1.5"/><text x="106" y="74" font-size="14" fill="var(--on-gold)" font-weight="700">Allusion</text><rect x="204" y="44" width="496" height="48" rx="10" fill="var(--surface)" stroke="var(--line)" stroke-width="1.5"/><text x="218" y="65" font-size="14" fill="var(--ink)" text-anchor="start" font-weight="700" font-style="italic">"A strap in time saves the roof."</text><text x="218" y="84" font-size="13" fill="var(--muted)" text-anchor="start">echoes "A stitch in time saves nine"</text><rect x="20" y="100" width="172" height="48" rx="24" fill="var(--gold)" stroke="none" stroke-width="1.5"/><text x="106" y="130" font-size="14" fill="var(--on-gold)" font-weight="700">Rhetorical question</text><rect x="204" y="100" width="496" height="48" rx="10" fill="var(--surface)" stroke="var(--line)" stroke-width="1.5"/><text x="218" y="121" font-size="13" fill="var(--ink)" text-anchor="start" font-weight="700" font-style="italic">"You lock your door every night; why not strap your roof?"</text><text x="218" y="140" font-size="13" fill="var(--muted)" text-anchor="start">makes homeowners reflect</text><rect x="20" y="156" width="172" height="48" rx="24" fill="var(--gold)" stroke="none" stroke-width="1.5"/><text x="106" y="186" font-size="14" fill="var(--on-gold)" font-weight="700">Rhyme</text><rect x="204" y="156" width="496" height="48" rx="10" fill="var(--surface)" stroke="var(--line)" stroke-width="1.5"/><text x="218" y="177" font-size="14" fill="var(--ink)" text-anchor="start" font-weight="700" font-style="italic">"Don\'t wait, hydrate!"</text><text x="218" y="196" font-size="13" fill="var(--muted)" text-anchor="start">matching sounds make the call to action stick</text><rect x="20" y="212" width="172" height="48" rx="24" fill="var(--gold)" stroke="none" stroke-width="1.5"/><text x="106" y="242" font-size="14" fill="var(--on-gold)" font-weight="700">Alliteration</text><rect x="204" y="212" width="496" height="48" rx="10" fill="var(--surface)" stroke="var(--line)" stroke-width="1.5"/><text x="218" y="233" font-size="14" fill="var(--ink)" text-anchor="start" font-weight="700" font-style="italic">"Swap soda, save smiles."</text><text x="218" y="252" font-size="13" fill="var(--muted)" text-anchor="start">repeated "s" sounds are catchy</text><rect x="20" y="268" width="172" height="48" rx="24" fill="var(--gold)" stroke="none" stroke-width="1.5"/><text x="106" y="298" font-size="14" fill="var(--on-gold)" font-weight="700">Pun</text><rect x="204" y="268" width="496" height="48" rx="10" fill="var(--surface)" stroke="var(--line)" stroke-width="1.5"/><text x="218" y="289" font-size="14" fill="var(--ink)" text-anchor="start" font-weight="700" font-style="italic">"Don\'t let sugar steal their sweet future."</text><text x="218" y="308" font-size="13" fill="var(--muted)" text-anchor="start">"sweet" means sugary and happy</text><rect x="20" y="326" width="680" height="28" rx="8" fill="var(--soft-blue)" stroke="none" stroke-width="1.5"/><text x="360" y="345" font-size="13" fill="var(--ink)">Q2(c): slogan (1) + technique named (1) + explanation linked to issue (2)</text></svg>',
    alt: 'Five slogan techniques, allusion, rhetorical question, rhyme, alliteration and pun, each with an example slogan and how it works, plus the 4-mark scheme.',
    caption: 'Name the technique and explain how it works for the audience.'
